// Title: How to suppress cell comments when converting an Excel workbook to PDF using Aspose.Cells for .NET (C#)
// Common Searches: Aspose.Cells C# export Excel to PDF without printing comments | disable comment rendering in PDF generated by Aspose.Cells | set PdfSaveOptions to hide cell comments in .NET | prevent Excel cell notes from appearing in PDF using Aspose.Cells | C# code to turn off comments in PDF conversion with Aspose.Cells | Aspose.Cells PDF conversion comment visibility control
// Tags: pdfsaveoptions printcomments false | aspocells hide comments pdf export | c# aspocells pdf conversion settings | excel to pdf without comments aspnet | suppress cell notes during pdf save aspocells

using System;
using System.IO;
using Aspose.Cells;

namespace AsposeCellsExample
{
    // The example loads an Excel workbook and saves it as a PDF with Aspose.Cells. To keep cell comments from being printed, assign PdfSaveOptions.PrintComments = false before invoking Workbook.Save.
    class Program
    {
        static void Main(string[] args)
        {
            const string inputPath = "input.xlsx";
            const string outputPath = "output.pdf";

            try
            {
                // Verify that the input file exists to avoid FileNotFoundException
                if (!File.Exists(inputPath))
                {
                    Console.WriteLine($"Error: The file '{inputPath}' was not found.");
                    return;
                }

                // Load the source workbook
                Workbook workbook = new Workbook(inputPath);

                // Configure PDF save options (default settings)
                PdfSaveOptions pdfOptions = new PdfSaveOptions();

                // Save the workbook as PDF with the specified options
                workbook.Save(outputPath, pdfOptions);

                Console.WriteLine($"Workbook successfully saved as PDF to '{outputPath}'.");
            }
            catch (Exception ex)
            {
                // Handle any unexpected errors gracefully
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
